187: async function guard(context: Parameters<Parameters<Hono["use"]>[1]>[0], next: () => Promise<void>, sessionToken: string) {
188:   if (context.req.method === "GET") return next();
189:   if (context.req.header("x-ub-session-token") !== sessionToken) {
190:     return context.json({ code: "INVALID_SESSION", message: "Missing or invalid local browser session token.", retryable: false }, 403);
191:   }
192:   return next();
193: }
194: 
195: function unavailable(context: { json: (body: unknown, status?: number) => Response }) {
196:   return context.json({ code: "ENGINE_UNAVAILABLE", message: "The workshop journey is not configured.", retryable: false }, 503);
197: }
198: 
199: function journeyError(context: { json: (body: unknown, status?: number) => Response }, error: unknown, validationMessage: string) {
200:   if (error instanceof ExperienceFailure) {
201:     return context.json({
202:       code: error.code,
203:       message: error.message,
204:       retryable: error.retryable,
205:       operationId: error.operationId,
206:     }, error.status as 400);
207:   }
208:   if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
209:     return context.json({ code: "WORKFLOW_CONFLICT", message: error.message, retryable: false }, 409);
210:   }
211:   if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: validationMessage, retryable: true }, 400);
212:   throw error;
213: }

