22: export async function probeNativeEngine(options: NativeClientOptions): Promise<NativeEngineStatus> {
23:   try {
24:     const client = createNativeClient(options);
25:     const [server, models] = await Promise.all([
26:       client.server.info(),
27:       client.model.list(),
28:     ]);
29:     const modelAvailable = models.data.some((model) =>
30:       `${model.providerID}/${model.id}` === FREE_DEEPSEEK_MODEL,
31:     );
32: 
33:     return nativeEngineStatusSchema.parse({
34:       available: true,
35:       serverVersion: server.version,
36:       model: FREE_DEEPSEEK_MODEL,
37:       modelAvailable,
38:       limitation: modelAvailable ? null : "The required free DeepSeek model is not in the native catalog.",
39:     });
40:   } catch (error) {
41:     return nativeEngineStatusSchema.parse({
42:       available: false,
43:       serverVersion: null,
44:       model: FREE_DEEPSEEK_MODEL,
45:       modelAvailable: false,
46:       limitation: error instanceof Error ? error.message : "Native OpenCode is unavailable.",
47:     });
