1: import { copyFile, mkdir, readFile, rename, writeFile } from "node:fs/promises";
2: import { dirname } from "node:path";
3: import { projectSchema, type Project } from "../workflow/model.ts";
4: 
5: export class RevisionConflict extends Error {}
6: 
7: export interface LoadResult {
8:   state: Project;
9:   source: "current" | "previous";
10:   corruptPath: string | null;
11: }
12: 
13: export class AtomicProjectStore {
14:   readonly previousPath: string;
15: 
16:   constructor(readonly path: string) {
17:     this.previousPath = `${path}.previous`;
18:   }
19: 
20:   private async parse(path: string): Promise<Project> {
21:     return projectSchema.parse(JSON.parse(await readFile(path, "utf8")));
22:   }
23: 
24:   async load(): Promise<LoadResult> {
25:     try {
26:       return { state: await this.parse(this.path), source: "current", corruptPath: null };
27:     } catch (currentError) {
28:       try {
29:         return { state: await this.parse(this.previousPath), source: "previous", corruptPath: this.path };
30:       } catch {
31:         throw currentError;
32:       }
33:     }
34:   }
35: 
36:   async initialize(project: Project): Promise<void> {
37:     await mkdir(dirname(this.path), { recursive: true });
38:     await writeFile(this.path, `${JSON.stringify(project, null, 2)}\n`, { flag: "wx" });
39:   }
40: 
41:   async save(expectedRevision: number, project: Project): Promise<Project> {
42:     const current = (await this.load()).state;
43:     if (current.revision !== expectedRevision) {
44:       throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${current.revision}.`);
45:     }
46:     const next = projectSchema.parse({ ...project, revision: expectedRevision + 1 });
47:     const temporaryPath = `${this.path}.tmp-${process.pid}-${Date.now()}`;
48:     await copyFile(this.path, this.previousPath);
49:     await writeFile(temporaryPath, `${JSON.stringify(next, null, 2)}\n`, { flag: "wx" });
50:     await rename(temporaryPath, this.path);
51:     return next;
52:   }
53: }

