80: export function rememberSession(project: Project, role: SpiritRole, sessionId: string): void {
81:   const existing = project.nativeSessions.find((item) => item.role === role);
82:   if (existing) existing.sessionId = sessionId;
83:   else project.nativeSessions.push({ role, sessionId });
84: }
