103:     proposal: input.proposal,
104:     openQuestions: input.openQuestions,
105:   };
106:   rememberSession(next, "oracle", input.sessionId);
107:   rememberTranscript(next, "oracle", `${input.clarification}\n\n${input.proposal}`);
108:   return projectSchema.parse(refreshNextAction(next));
109: }
