111: export function approveProduct(project: Project): Project {
112:   const next = clone(project);
113:   if (next.product.status !== "PROPOSED" || !next.product.proposal) {
114:     throw new WorkflowConflict("Approve the current Oracle proposal before planning begins.");
115:   }
116:   next.product.status = "APPROVED";
117:   rememberTranscript(next, "user", "Approved the Oracle proposal.");
118:   return projectSchema.parse(refreshNextAction(next));
