121: export function grantMakerScope(project: Project, statement: string): Project {
122:   const next = clone(project);
123:   const unresolved = next.sections.filter((section) => section.status !== "APPROVED");
124:   if (unresolved.length) throw new WorkflowConflict("Maker scope waits until every current section is approved.");
125:   if (next.product.status !== "APPROVED") throw new WorkflowConflict("Maker scope waits for an approved product.");
126:   next.makerScope = { status: "GRANTED", statement };
127:   rememberTranscript(next, "user", `Granted Maker scope: ${statement}`);
128:   return projectSchema.parse(refreshNextAction(next));
129: }
