149:   const next = clone(project);
150:   const capability = next.capabilities.find((item) => item.id === id);
151:   if (!capability) throw new WorkflowConflict(`Unknown capability: ${id}`);
152:   capability.observedOutcome = outcome;
153:   capability.availability = availability;
154:   return projectSchema.parse(refreshNextAction(next));
