      );
    }
  }
  if (addresses.length === 0) {
    throw new NetworkPolicyError("OPENCODE_HOST_BLOCKED", "OpenCode host did not resolve to an address.");
  }

  for (const address of addresses) {
    const value = address.address;
    const family = address.family || (isIP(value) === 6 ? 6 : 4);
    if (metadataAddresses.has(value)) {
      throw new NetworkPolicyError("OPENCODE_PRIVATE_ADDRESS", "The OpenCode host resolves to a cloud metadata address.");
    }
    if (family === 4) {
      if (isBlockedIPv4(value)) {
        throw new NetworkPolicyError("OPENCODE_PRIVATE_ADDRESS", "The OpenCode host resolves to a blocked address.");
      }
      if (!loopback && isPrivateIPv4(value) && !policy.allowPrivateNetwork) {
        throw new NetworkPolicyError(
          "OPENCODE_PRIVATE_ADDRESS",
          "The OpenCode host resolves to a private address. Set UB_OPENCODE_ALLOW_PRIVATE_NETWORK only when that network is intended.",
        );
      }
      if (loopback && !value.startsWith("127.")) {
        throw new NetworkPolicyError("OPENCODE_HOST_BLOCKED", "The loopback OpenCode host resolved to a non-loopback address.");
      }
    } else {
      if (isBlockedIPv6(value)) {
        throw new NetworkPolicyError("OPENCODE_PRIVATE_ADDRESS", "The OpenCode host resolves to a blocked IPv6 address.");
      }
      if (!loopback && isPrivateIPv6(value) && !policy.allowPrivateNetwork) {
        throw new NetworkPolicyError(
          "OPENCODE_PRIVATE_ADDRESS",
          "The OpenCode host resolves to a private IPv6 address. Set UB_OPENCODE_ALLOW_PRIVATE_NETWORK only when that network is intended.",
        );
      }
      if (loopback && value !== "::1") {
        throw new NetworkPolicyError("OPENCODE_HOST_BLOCKED", "The loopback OpenCode host resolved to a non-loopback address.");
      }
    }
  }
  return addresses;
}

function abortWithTimeout(signal: AbortSignal | null | undefined, timeoutMs: number): { signal: AbortSignal; clear: () => void } {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new Error("OpenCode request timed out.")), timeoutMs);
  timer.unref?.();
  const onAbort = () => controller.abort(signal?.reason);
  if (signal) {
    if (signal.aborted) controller.abort(signal.reason);
    else signal.addEventListener("abort", onAbort, { once: true });
  }
  return {
    signal: controller.signal,
    clear: () => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
    },
  };
}

function boundedBody(body: ReadableStream<Uint8Array> | null, limit: number): ReadableStream<Uint8Array> | null {
  if (!body) return null;
  let seen = 0;
  return body.pipeThrough(new TransformStream<Uint8Array, Uint8Array>({
    transform(chunk, controller) {
      seen += chunk.byteLength;
      if (seen > limit) {
        controller.error(new NetworkPolicyError("OPENCODE_RESPONSE_TOO_LARGE", "The OpenCode response exceeded the configured size limit."));
        return;
      }
      controller.enqueue(chunk);
    },
  }));
}

export function createSafeFetch(policy: NetworkPolicy): typeof fetch {
  const fetchImpl = policy.fetchImpl ?? globalThis.fetch;
  const timeoutMs = policy.requestTimeoutMs ?? 300_000;
  const maxBytes = policy.maxResponseBytes ?? 8 * 1024 * 1024;

  return async function safeFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
    const requestUrl = input instanceof Request ? input.url : input.toString();
    const url = validateBaseUrlSyntax(requestUrl);
    await assertAllowedUrl(url, policy);
    const timeout = abortWithTimeout(init?.signal, timeoutMs);
    try {
      const response = await fetchImpl(input, {
        ...init,
        redirect: "manual",
        cache: "no-store",
        credentials: "omit",
        referrerPolicy: "no-referrer",
        signal: timeout.signal,
      });
      if (response.status >= 300 && response.status < 400) {
        await response.body?.cancel();
        throw new NetworkPolicyError("OPENCODE_REDIRECT_BLOCKED", "The OpenCode server attempted an HTTP redirect. Redirects are not followed.");
      }
      const contentLength = Number(response.headers.get("content-length") ?? "0");
      if (Number.isFinite(contentLength) && contentLength > maxBytes) {
        await response.body?.cancel();
        throw new NetworkPolicyError("OPENCODE_RESPONSE_TOO_LARGE", "The OpenCode response exceeded the configured size limit.");
      }
      const body = boundedBody(response.body, maxBytes);
      return new Response(body, {
        status: response.status,
        statusText: response.statusText,
        headers: response.headers,
      });
    } catch (error) {
      if (error instanceof NetworkPolicyError) throw error;
      if (timeout.signal.aborted) {
        throw new NetworkPolicyError("OPENCODE_TIMEOUT", "The OpenCode request timed out.");
      }
      throw error;
    } finally {
      timeout.clear();
    }
  } as typeof fetch;
}

export function sanitizeNetworkError(error: unknown): string {
  if (error instanceof NetworkPolicyError) return error.message;
  const message = error instanceof Error ? error.message : "OpenCode could not be reached.";
  return redactText(message);
}

import { homedir } from "node:os";

export interface RedactOptions {
  /** Redact the current user's home directory and common private mount paths. */
  hideLocalPaths?: boolean;
  /** Replace prompt/tool text entirely. Used when the operator opts into private prompts. */
  hidePromptText?: boolean;
}

const secretPatterns: Array<[RegExp, string]> = [
  [/(authorization\s*[:=]\s*)(?:basic|bearer|digest)\s+[A-Za-z0-9._~+/=-]+/gi, "$1[REDACTED]"],
  [/((?:proxy-)?authorization\s*[:=]\s*)[^\s,;]+/gi, "$1[REDACTED]"],
  [/((?:set-)?cookie\s*[:=]\s*)[^\r\n]+/gi, "$1[REDACTED]"],
  [/((?:OPENCODE_PASSWORD|OPENCODE_SERVER_PASSWORD|UB_ACCESS_PASSWORD|UB_SESSION_TOKEN|SENTRY_AUTH_TOKEN)\s*[=:]\s*)[^\s,;]+/gi, "$1[REDACTED]"],
  [/\b(?:sk|rk|pk)-[A-Za-z0-9_-]{16,}\b/g, "[REDACTED_API_KEY]"],
  [/\bgh[pousr]_[A-Za-z0-9]{20,}\b/g, "[REDACTED_GITHUB_TOKEN]"],
  [/\bxox[abprs]-[A-Za-z0-9-]{10,}\b/g, "[REDACTED_SLACK_TOKEN]"],
  [/\bAIza[0-9A-Za-z_-]{30,}\b/g, "[REDACTED_GOOGLE_KEY]"],
  [/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g, "[REDACTED_JWT]"],
  [/https:\/\/[^@\s/]+@[^/\s]+\/\d+/g, "[REDACTED_SENTRY_DSN]"],
  [/(https?:\/\/)([^/\s:@]+):([^/\s@]+)@/gi, "$1[REDACTED]@"],
  [/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, "[REDACTED_EMAIL]"],
];

function redactPaths(text: string): string {
  const home = homedir().replace(/[\\/]+$/, "");
  let result = text;
  if (home && home !== "/") {
    result = result.replaceAll(home, "[REDACTED_HOME]");
  }
  return result
    .replace(/\/var\/data\/[A-Za-z0-9._/-]+/g, "[REDACTED_DATA_PATH]")
    .replace(/\/(?:home|Users)\/[A-Za-z0-9._-]+(?:\/[A-Za-z0-9._/-]+)?/g, "[REDACTED_USER_PATH]");
}

export function redactText(value: string, options: RedactOptions = {}): string {
  if (options.hidePromptText) return "[REDACTED_PROMPT]";
  let result = value;
  for (const [pattern, replacement] of secretPatterns) {
    result = result.replace(pattern, replacement);
  }
  if (options.hideLocalPaths) result = redactPaths(result);
  return result;
}

export function redactUnknown(value: unknown, options: RedactOptions = {}, depth = 0): unknown {
  if (depth > 8) return "[REDACTED_DEPTH]";
  if (typeof value === "string") return redactText(value, options);
  if (value === null || typeof value === "number" || typeof value === "boolean") return value;
  if (Array.isArray(value)) return value.slice(0, 500).map((item) => redactUnknown(item, options, depth + 1));
  if (typeof value === "object") {
    const output: Record<string, unknown> = {};
    for (const [key, entry] of Object.entries(value as Record<string, unknown>).slice(0, 500)) {
      if (/^(authorization|cookie|set-cookie|password|secret|token|api[_-]?key|dsn)$/i.test(key)) {
        output[key] = "[REDACTED]";
      } else {
        output[key] = redactUnknown(entry, options, depth + 1);
      }
    }
    return output;
  }
  return String(value);
}

export function redactError(error: unknown, options: RedactOptions = {}): { name: string; message: string; code: string | null } {
  const source = error instanceof Error ? error : new Error(String(error));
  const code = (source as NodeJS.ErrnoException).code;
  return {
    name: source.name,
    message: redactText(source.message, options),
    code: typeof code === "string" ? code : null,
  };
}

function redactRecord(value: unknown, options: RedactOptions): unknown {
  return redactUnknown(value, options);
}

/**
 * Removes request content, user identity, query strings and credentials from a
 * Sentry event. The SDK already disables most collection; this is a final
 * defense-in-depth pass before transport.
 */
export function sanitizeSentryEvent<T extends Record<string, unknown>>(event: T, options: RedactOptions = {}): T {
  const copy = structuredClone(event) as Record<string, unknown>;
  if (copy.request && typeof copy.request === "object") {
    const request = copy.request as Record<string, unknown>;
    delete request.data;
    delete request.headers;
    delete request.cookies;
    delete request.query_string;
    if (typeof request.url === "string") request.url = request.url.split("?")[0];
  }
  delete copy.user;
  if (typeof copy.message === "string") copy.message = redactText(copy.message, options);
  if (typeof copy.logentry === "object" && copy.logentry) {
    const logentry = copy.logentry as Record<string, unknown>;
    if (typeof logentry.message === "string") logentry.message = redactText(logentry.message, options);
    delete logentry.params;
  }
  if (typeof copy.exception === "object" && copy.exception) {
    const exception = copy.exception as Record<string, unknown>;
    if (Array.isArray(exception.values)) {
      exception.values = exception.values.map((value) => {
        if (!value || typeof value !== "object") return value;
        const entry = { ...(value as Record<string, unknown>) };
        if (typeof entry.value === "string") entry.value = redactText(entry.value, options);
        return entry;
      });
    }
  }
  if (Array.isArray(copy.breadcrumbs)) {
    copy.breadcrumbs = copy.breadcrumbs.map((crumb) => {
      if (!crumb || typeof crumb !== "object") return crumb;
      const entry = { ...(crumb as Record<string, unknown>) };
      if (typeof entry.message === "string") entry.message = redactText(entry.message, options);
      delete entry.data;
      return entry;
    });
  }
  if (copy.extra) copy.extra = redactRecord(copy.extra, options);
  if (copy.contexts) copy.contexts = redactRecord(copy.contexts, options);
  return copy as T;
}

export function safePublicError(error: unknown, fallback: string, options: RedactOptions = {}): string {
  const message = error instanceof Error ? error.message : "";
  if (!message) return fallback;
  const redacted = redactText(message, options);
  return redacted.length > 400 ? `${redacted.slice(0, 397)}...` : redacted;
}

