private assertBudget(info: { model?: { providerID: string; id: string }; cost: number; tokens?: { input: number; output: number; reasoning: number } }): void {
  const selected = info.model ? `${info.model.providerID}/${info.model.id}` : "";
  if (selected !== FREE_DEEPSEEK_MODEL) {
    throw new NativeSessionError("MODEL_CHANGED", "Native session left the required free DeepSeek model. No substitute model is allowed.");
