test("rejects traversal and symlink escapes from a workspace root", async () => {
  assert.throws(() => assertSafeRelativePath("../REDACTED"), WorkspacePolicyError);
  assert.throws(() => assertSafeRelativePath("nested/../../REDACTED"), WorkspacePolicyError);
  assert.throws(() => assertSafeRelativePath("bad\0name"), WorkspacePolicyError);

  const parent = await mkdtemp(join(tmpdir(), "ub-workspace-"));
  const root = join(parent, "root");
  const outside = join(parent, "outside");
  await mkdir(root);
  await mkdir(outside);
  await writeFile(join(outside, "REDACTED.txt"), "outside");
  await symlink(join(outside, "REDACTED.txt"), join(root, "escape.txt"));

  await assert.rejects(resolveStaticFile(root, "escape.txt"), /escaped the web root|symlink/i);
  assert.equal(await resolveStaticFile(root, "missing.txt"), null);

  const linkedRoot = join(parent, "linked-root");
  await symlink(outside, linkedRoot);
  await assert.rejects(
    canonicalizeDirectoryRoot(linkedRoot, { allowedParent: root }),
    WorkspacePolicyError,
  );
});

test("rejects special files and non-files for persisted state", async () => {
  const directory = await mkdtemp(join(tmpdir(), "ub-special-"));
  await assert.rejects(assertRegularFile(directory), WorkspacePolicyError);
  const file = join(directory, "state.json");
  await writeFile(file, "{}");
  await assertRegularFile(file);
  await writeFile(join(directory, "target.json"), "{}");
  await symlink(join(directory, "target.json"), join(directory, "linked.json"));
  await assert.rejects(assertRegularFile(join(directory, "linked.json")), WorkspacePolicyError);
});

test("accepts loopback HTTP but requires HTTPS and an explicit host for remote OpenCode", async () => {
  assert.equal(validateBaseUrlSyntax("http://127.0.0.1:4096").hostname, "127.0.0.1");
  assert.throws(() => validateBaseUrlSyntax("REDACTED"), NetworkPolicyError);
  assert.throws(() => validateBaseUrlSyntax("file:///tmp/opencode.sock"), NetworkPolicyError);
  assert.throws(() => validateBaseUrlSyntax("http://127.0.0.1:4096/?token=REDACTED"), NetworkPolicyError);

  await assertAllowedUrl(new URL("http://127.0.0.1:4096"), { baseUrl: "http://127.0.0.1:4096" });
  await assert.rejects(
    assertAllowedUrl(new URL("http://opencode.example.com"), { baseUrl: "http://opencode.example.com" }),
    (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_INSECURE_REMOTE",
  );
  await assert.rejects(
    assertAllowedUrl(new URL("https://opencode.example.com"), { baseUrl: "https://opencode.example.com" }),
    (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_HOST_BLOCKED",
  );
});

test("blocks metadata, loopback rebinding, and private DNS unless explicitly allowed", async () => {
  const base = {
    baseUrl: "https://opencode.example.com",
    allowedHosts: ["opencode.example.com"],
  };
  await assert.rejects(
    assertAllowedUrl(new URL(base.baseUrl), { ...base, resolver: async () => [{ address: "169.254.169.254", family: 4 }] }),
    (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_PRIVATE_ADDRESS",
  );
  await assert.rejects(
    assertAllowedUrl(new URL(base.baseUrl), { ...base, resolver: async () => [{ address: "127.0.0.1", family: 4 }] }),
    (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_PRIVATE_ADDRESS",
  );
  await assert.rejects(
    assertAllowedUrl(new URL(base.baseUrl), { ...base, resolver: async () => [{ address: "10.1.2.3", family: 4 }] }),
    (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_PRIVATE_ADDRESS",
  );
  await assertAllowedUrl(new URL(base.baseUrl), {
    ...base,
    allowPrivateNetwork: true,
    resolver: async () => [{ address: "10.1.2.3", family: 4 }],
  });
});

test("revalidates DNS on every request and blocks redirects and oversized bodies", async () => {
  let lookups = 0;
  let requestCount = 0;
  const safeFetch = createSafeFetch({
    baseUrl: "https://opencode.example.com",
    allowedHosts: ["opencode.example.com"],
    requestTimeoutMs: 500,
    maxResponseBytes: 16,
    resolver: async () => {
      lookups += 1;
      return lookups === 1 ? [{ address: "8.8.8.8", family: 4 }] : [{ address: "127.0.0.1", family: 4 }];
    },
    fetchImpl: async () => {
      requestCount += 1;
      return new Response("ok", { status: 200 });
    },
  });

  const first = await safeFetch("https://opencode.example.com/health");
  assert.equal(await first.text(), "ok");
  await assert.rejects(
    safeFetch("https://opencode.example.com/health"),
    (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_PRIVATE_ADDRESS",
  );
  assert.equal(requestCount, 1);

  const redirecting = createSafeFetch({
    baseUrl: "https://opencode.example.com",
    allowedHosts: ["opencode.example.com"],
    resolver: async () => [{ address: "8.8.8.8", family: 4 }],
    fetchImpl: async () => new Response(null, { status: 302, headers: { location: "http://127.0.0.1:4096" } }),
  });
  await assert.rejects(redirecting("https://opencode.example.com"), /redirect/i);

  const oversized = createSafeFetch({
    baseUrl: "https://opencode.example.com",
    allowedHosts: ["opencode.example.com"],
    maxResponseBytes: 8,
    resolver: async () => [{ address: "8.8.8.8", family: 4 }],
    fetchImpl: async () => new Response("this is much longer than eight bytes", { status: 200 }),
  });
  const response = await oversized("https://opencode.example.com");
  await assert.rejects(response.text(), (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_RESPONSE_TOO_LARGE");
});

test("times out a hanging OpenCode request without following it", async () => {
  const safeFetch = createSafeFetch({
    baseUrl: "https://opencode.example.com",
    allowedHosts: ["opencode.example.com"],
    requestTimeoutMs: 20,
    resolver: async () => [{ address: "8.8.8.8", family: 4 }],
    fetchImpl: async (_input, init) => new Promise<Response>((_resolve, reject) => {
      init?.signal?.addEventListener("abort", () => reject(new Error("aborted")), { once: true });
    }),
  });
  await assert.rejects(
    safeFetch("https://opencode.example.com/slow"),
    (error: unknown) => error instanceof NetworkPolicyError && error.code === "OPENCODE_TIMEOUT",
  );
});

test("loadConfig enforces mode-specific secure defaults", () => {
  const local = loadConfig({ NODE_ENV: "development", OPENCODE_BASE_URL: "http://127.0.0.1:4096" });
  assert.equal(local.mode, "local");
  assert.equal(local.hostname, "127.0.0.1");
  assert.equal(local.access, null);
  assert.equal(runtimeConfigSchema.parse(publicRuntimeConfig(local)).demoWorkspace, true);

  assert.throws(() => loadConfig({ UB_MODE: "local", UB_HOST: "0.0.0.0" }), /loopback/i);
  assert.throws(() => loadConfig({ UB_MODE: "hosted-demo", UB_PUBLIC_URL: "https://demo.example.com" }), /UB_SESSION_TOKEN/);
  assert.throws(() => loadConfig({
    UB_MODE: "hosted-demo",
    UB_PUBLIC_URL: "https://demo.example.com",
    UB_SESSION_TOKEN: "token",
  }), /UB_ACCESS_PASSWORD/);
  assert.throws(() => loadConfig({
    UB_MODE: "hosted-demo",
    UB_PUBLIC_URL: "http://demo.example.com",
    UB_SESSION_TOKEN: "token",
    UB_ACCESS_PASSWORD: "REDACTED",
  }), /HTTPS/);

  const hosted = loadConfig({
    UB_MODE: "hosted-demo",
    UB_PUBLIC_URL: "https://demo.example.com",
    UB_SESSION_TOKEN: "token",
    UB_ACCESS_PASSWORD: "REDACTED",
  });
  assert.equal(hosted.mode, "hosted-demo");
  assert.equal(hosted.hostname, "0.0.0.0");
  assert.equal(hosted.access?.username, "unfinished-business");
  assert.ok(isLoopbackHost("localhost"));
});

test("redacts credentials, cookies, provider keys, DSNs, identity, and local paths", () => {
  const source = [
    "Authorization: Bearer abc.def.ghi",
    "Cookie: session=superREDACTED",
    "OPENCODE_PASSWORD=REDACTED",
    "key REDACTED",
    "dsn https://public@o123.ingest.sentry.io/456",
    "user person@example.com",
    `path ${homedir()}/private/project`,
  ].join("\n");
  const redacted = redactText(source, { hideLocalPaths: true });
  for (const REDACTED of ["abc.def.ghi", "superREDACTED", "REDACTED", "REDACTED", "person@example.com", `${homedir()}/private`]) {
    assert.equal(redacted.includes(REDACTED), false, REDACTED);
  }
  assert.match(redacted, /\[REDACTED\]/);
  assert.match(redacted, /\[REDACTED_HOME\]/);
  assert.equal(safePublicError(new Error("OPENCODE_PASSWORD=REDACTED"), "fallback"), "OPENCODE_PASSWORD=[REDACTED]");
  assert.match(redactError(new Error("Authorization: Bearer REDACTED"))!.message, /\[REDACTED\]/);
  assert.equal((redactUnknown({ REDACTED: "REDACTED", nested: { token: "REDACTED" } }) as { REDACTED: string }).REDACTED, "[REDACTED]");
});

test("sanitizes Sentry events and structured logs independently", () => {
  const event = sanitizeSentryEvent({
    message: "request failed for person@example.com",
    request: { url: "https://demo.example.com/api?token=REDACTED", headers: { authorization: "Bearer REDACTED" }, data: { REDACTED: "REDACTED" }, cookies: "a=b" },
    user: { email: "person@example.com" },
    exception: { values: [{ value: "OPENCODE_PASSWORD=REDACTED" }] },
    breadcrumbs: [{ message: "Cookie: REDACTED", data: { token: "REDACTED" } }],
    extra: { apiKey: "REDACTED" },
  });
  assert.equal(JSON.stringify(event).includes("REDACTED"), false);
  assert.equal(JSON.stringify(event).includes("person@example.com"), false);
  assert.equal((event as { request: { url: string } }).request.url, "https://demo.example.com/api");
  assert.equal((event as { user?: unknown }).user, undefined);

  const lines: string[] = [];
  const logger = createLogger({ sink: (line) => lines.push(line), redact: { hideLocalPaths: true } });
  logger.error("failed", { authorization: "Bearer REDACTED", REDACTED: "REDACTED", path: `${homedir()}/x` });
  assert.equal(lines[0].includes("REDACTED"), false);
  assert.equal(lines[0].includes("REDACTED"), false);
});

import assert from "node:assert/strict";
import { mkdtemp, readFile, readdir, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { AtomicProjectStore, RevisionConflict, StateError } from "../src/server/store/atomic-project-store.ts";
import { createProject, migrateProject, payloadHash, projectSchema } from "../src/server/workflow/model.ts";
import { WorkflowService } from "../src/server/workflow/service.ts";
import { reviseSection } from "../src/server/workflow/transitions.ts";
import { applyRetention, retentionPolicy } from "../src/server/workflow/retention.ts";

async function fixture() {
  const directory = await mkdtemp(join(tmpdir(), "ub-store-hardening-"));
  const path = join(directory, "project.json");
  const store = new AtomicProjectStore(path, { backups: 3, corruptFiles: 3, lockTimeoutMs: 100 });
  await store.initialize(createProject("/workspace"));
  return { directory, path, store };
}

test("preserves the corrupt current file and quarantines it before recovery", async () => {
  const { directory, path, store } = await fixture();
  await store.save(0, reviseSection((await store.load()).state, "control", "v1"));
  await writeFile(path, "{corrupt", "utf8");
  const recovered = await store.load();
  assert.equal(recovered.source, "previous");
  assert.equal(recovered.corruptPath, path);
  assert.ok(recovered.quarantinePath);
  assert.equal(await readFile(path, "utf8"), "{corrupt");
  assert.equal(await readFile(recovered.quarantinePath!, "utf8"), "{corrupt");
  assert.match(recovered.quarantinePath!, /project\.json\.corrupt-/);
  assert.ok((await readdir(directory)).some((name) => name.startsWith("backups")));
});

test("rejects corrupt state when no valid previous snapshot exists without overwriting it", async () => {
  const { directory, path, store } = await fixture();
  await writeFile(path, "{totally broken");
  await writeFile(`${path}.previous`, "{also broken");
  await assert.rejects(store.load(), (error: unknown) => error instanceof StateError && error.code === "STATE_CORRUPT");
  assert.equal(await readFile(path, "utf8"), "{totally broken");
  assert.equal(await readFile(`${path}.previous`, "utf8"), "{also broken");
});

test("refuses a newer schema version and preserves the original", async () => {
  const { path, store } = await fixture();
  await writeFile(path, JSON.stringify({ ...createProject("/workspace"), schemaVersion: 99 }));
  await assert.rejects(store.load(), /newer than this build/i);
  assert.match(await readFile(path, "utf8"), /"schemaVersion":99/);
});

test("migrates a v1 snapshot to the current schema without resetting content", () => {
  const current = createProject("/workspace");
  const legacy = { ...current, schemaVersion: 1, createdAt: undefined, updatedAt: undefined, mode: undefined };
  const migrated = migrateProject(legacy);
  assert.equal(migrated.migrated, true);
  assert.equal(migrated.fromVersion, 1);
  assert.equal(migrated.project.schemaVersion, 2);
  assert.equal(migrated.project.mode, "local");
  assert.equal(migrated.project.demoWorkspace, true);
  assert.equal(projectSchema.parse(migrated.project).revision, current.revision);
});

test("reports lock contention and maps write failures without replacing state", async () => {
  const { path, store } = await fixture();
  await writeFile(`${path}.lock`, "held", { mode: 0o600 });
  await assert.rejects(store.save(0, (await store.load()).state), (error: unknown) => error instanceof StateError && error.code === "STATE_BUSY");
  await writeFile(`${path}.lock`, "", { mode: 0o600 });

  const parentFile = join(await mkdtemp(join(tmpdir(), "ub-disk-")), "not-a-directory");
  await writeFile(parentFile, "file");
  const broken = new AtomicProjectStore(join(parentFile, "project.json"));
  await assert.rejects(
    broken.initialize(createProject("/workspace")),
    (error: unknown) => error instanceof StateError && ["STATE_WRITE_FAILED", "STATE_READ_ONLY"].includes(error.code),
  );
});

test("retains bounded actions, operations, evidence, transcript, and drafts", () => {
  const project = createProject("/workspace");
  for (let index = 0; index < 10; index += 1) {
    project.actions.push({ id: `a-${index}`, payloadHash: payloadHash({ index }), resultRevision: index, createdAt: new Date().toISOString() });
    project.operations.push({ id: `o-${index}`, kind: "guide", payloadHash: "x", nativeSessionId: null, nativeMessageId: null, status: "FAILED", result: "x", startedAt: null, finishedAt: null });
    project.transcript.push({ id: `t-${index}`, spirit: "system", text: "x", createdAt: new Date().toISOString() });
  }
  const retained = applyRetention(project, {
    actions: 3,
    operations: 2,
    evidence: 2,
    transcript: 4,
    witnessDrafts: 2,
    backups: 1,
    corruptFiles: 1,
    backupMaxAgeDays: 1,
  });
  assert.deepEqual(retained.project.actions.map((item) => item.id), ["a-7", "a-8", "a-9"]);
  assert.deepEqual(retained.project.operations.map((item) => item.id), ["o-8", "o-9"]);
  assert.equal(retained.project.transcript.length, 4);
  assert.equal(retentionPolicy({
    actions: 3,
    operations: 2,
    evidence: 2,
    transcript: 4,
    witnessDrafts: 2,
    backups: 1,
    corruptFiles: 1,
    backupMaxAgeDays: 1,
  }).length, 6);
});

test("marks in-flight operations unknown after restart and never repeats them", async () => {
  const { store } = await fixture();
  const workflow = new WorkflowService(store);
  const project = (await store.load()).state;
  project.operations.push({
    id: "11111111-1111-4111-8111-111111111111",
    kind: "maker",
    payloadHash: "hash",
    nativeSessionId: "ses_restart",
    nativeMessageId: null,
    status: "RUNNING",
    result: null,
    startedAt: new Date().toISOString(),
    finishedAt: null,
  });
  project.operations.push({
    id: "22222222-2222-4222-8222-222222222222",
    kind: "guide",
    payloadHash: "hash",
    nativeSessionId: null,
    nativeMessageId: null,
    status: "WAITING_PERMISSION",
    result: null,
    startedAt: new Date().toISOString(),
    finishedAt: null,
  });
  await store.save(0, project);

  const recovered = await workflow.recoverAfterRestart();
  assert.equal(recovered?.recovered, 2);
  const after = await store.load();
  for (const operation of after.state.operations) {
    assert.equal(operation.status, "UNKNOWN");
    assert.match(operation.result ?? "", /restarted|not repeated/i);
  }
  assert.match(after.state.nextAction, /Reconcile/i);
  assert.equal(await workflow.recoverAfterRestart(), null);
});

test("keeps rolling backups bounded and does not overwrite a corrupt current with a backup", async () => {
  const { directory, path, store } = await fixture();
  let project = (await store.load()).state;
  for (let revision = 0; revision < 5; revision += 1) {
    project = (await store.save(revision, reviseSection(project, "control", `revision ${revision}`))).project;
  }
  const backups = await readdir(join(directory, "backups"));
  assert.ok(backups.length <= 3, backups.join(", "));
  assert.equal(await readFile(`${path}.previous`, "utf8") !== "", true);
});

test("rejects a reused action with a different payload and nested payload hashes are canonical", async () => {
  const { store } = await fixture();
  const workflow = new WorkflowService(store);
  assert.equal(payloadHash({ a: 1, b: { c: 2, d: 3 } }), payloadHash({ b: { d: 3, c: 2 }, a: 1 }));
  const first = await workflow.execute("action", { content: "v1" }, 0, (project) => reviseSection(project, "control", "v1"));
  assert.equal(first.duplicate, false);
  const duplicate = await workflow.execute("action", { content: "v1" }, 0, (project) => project);
  assert.equal(duplicate.duplicate, true);
  await assert.rejects(workflow.execute("action", { content: "v2" }, 1, (project) => project), RevisionConflict);
});

